-- Restructures father_activities content into granular fields for the activity detail UI.
-- Adds short_description (card teaser), steps (ordered how-to list), and why_this
-- (father-facing rationale, written to speak directly to him). The existing description
-- column is untouched; these are additive fields derived by splitting its content (plus
-- next_step/source for context). No doctor-clearance columns here: unlike mother_activities,
-- none of these activities involve the father's own postpartum body.
--
-- Covers all 160 father_activities rows: 150 from 20260908090000_father_activities_refresh
-- (125 shared + 15 caesarean-specific + 10 vaginal-specific) and 10 preterm/NICU rows
-- (ids starting 'pt-') from 20260907090000_preterm_nicu_module, which the refresh migration
-- explicitly does not touch.

alter table father_activities add column if not exists short_description text;
alter table father_activities add column if not exists steps jsonb;
alter table father_activities add column if not exists why_this text;

update father_activities set
  short_description = v.short_description,
  steps = v.steps,
  why_this = v.why_this
from (values
  ('take-the-night-shift-m1', 'The single most useful thing you can do for her in month one.', '["Pick a block of the night — say 9pm to 1am — where you''re fully on duty.", "Let her sleep without listening for the baby at all.", "If she''s breastfeeding, bring the baby to her to feed, then take the baby back and handle the nappy and settling yourself."]'::jsonb, 'Broken sleep is the single biggest driver of postpartum depression — this is the most useful thing you can do for her in month one.'),
  ('be-the-gatekeeper-m1', 'You handle the visitors so she never has to be the one saying no.', '["Decide who comes, when, for how long, and when they leave.", "Say it plainly to anyone asking: \"We''re keeping things quiet for a few weeks, we''ll let you know when we''re ready.\"", "Take the awkwardness of saying no onto yourself, every time."]'::jsonb, 'This is a genuinely useful job that costs you nothing and her nothing — she should never have to be the one saying no or feeling rude about it.'),
  ('bring-food-and-water-unasked-m1', 'She''ll forget to eat and drink while feeding — bring it before she has to ask.', '["Put water beside her every time she sits down.", "Bring food she can eat one-handed.", "Don''t ask if she wants anything — just bring it."]'::jsonb, 'She''ll say no out of habit if you ask, so don''t ask — just bring it, every time.'),
  ('learn-what-her-recovery-involves-m1', 'Learn what actually happens to her body after birth, before it surprises you.', '["Read up on what happens after birth: bleeding for weeks, afterpains, engorgement, hormone crashes, hair loss, night sweats.", "Note which of these is normal and which needs a doctor."]'::jsonb, 'Knowing what''s normal means you can be calm when she needs calm, and worried at the right moments instead of alarmed by something ordinary.'),
  ('watch-for-warning-signs-m1', 'Know the red flags she might be too exhausted to notice or report herself.', '["Learn the red flags: fever over 38°C, heavy bleeding soaking a pad an hour, foul-smelling discharge, severe headache, chest pain, calf pain or swelling, or thoughts of harming herself or the baby.", "Watch for them yourself, since exhausted people minimise their own symptoms.", "Call the doctor today if you see any of them."]'::jsonb, 'You are the second set of eyes — exhausted people minimise, and any one of these needs calling the doctor today, not waiting to see.'),
  ('never-shake-a-baby-m1', 'The single most important thing in this guide — make a plan now, before you need it.', '["Know that crying peaks at six to eight weeks, and some babies cry for hours with nothing wrong and nothing that works.", "If you feel yourself reaching the edge, put the baby down on their back somewhere safe.", "Walk into another room, shut the door, and let them cry for five or ten minutes while you breathe.", "Tell your partner this is your plan, and ask her to do the same."]'::jsonb, 'Feeling a surge of anger toward a crying baby does not make you a bad father, but acting on it causes permanent brain injury or death in seconds — a crying baby alone in a cot is completely safe, and that''s the plan worth having ready before you need it.'),
  ('spot-it-if-she-cannot-say-it-m1', 'You''ll probably notice her postpartum depression before she does.', '["Watch for persistent low mood, hopelessness, difficulty bonding with the baby, rage out of proportion, or constant anxiety lasting more than two weeks.", "Treat some signs as same-day emergencies: talk of harming herself or the baby, saying the baby would be better off without her, seeing or hearing things you cannot, confusion, or being unable to sleep even when the baby sleeps.", "Take her to a doctor or hospital immediately if you see any emergency sign — do not wait to see if it passes, and do not leave her alone.", "Tell her plainly that you are not going anywhere and that getting help is how this gets better."]'::jsonb, 'Postpartum psychosis is rare, but it is a genuine medical emergency and very treatable with prompt care — she may be frightened that saying it aloud means the baby will be taken away, so your calm plainness matters.'),
  ('do-the-first-nappy-m1', 'Change the first nappy, then keep changing them — this is how you catch up on confidence.', '["Change the first nappy yourself.", "Keep changing them after that, along with baths, burping and settling.", "Accept being bad at it at first — that''s how you get better."]'::jsonb, 'These are the tasks where fathers most often defer to the mother and never catch up — starting on day one is how you avoid that.'),
  ('skin-to-skin-yours-too-m1', 'Skin-to-skin isn''t only a mother thing — it works on you too.', '["Bare your chest and lay the baby on you.", "Cover both of you with a blanket.", "Stay like that as long as you both want."]'::jsonb, 'This regulates your baby''s temperature and heart rate and floods you with oxytocin too — fathers who do this early report feeling connected to their baby much sooner.'),
  ('talk-to-your-baby-m1', 'Your voice is distinctive and calming to your baby — use it constantly.', '["Talk to your baby while you change them, carry them, or walk with them.", "Say whatever comes to mind — cricket scores, what you''re cooking, what you''re worried about.", "Don''t worry about the content — the sound is the point."]'::jsonb, 'Your voice is lower than hers and babies find it distinctive and calming — what you say matters far less than that you keep saying it.'),
  ('find-your-own-hold-m1', 'Find your own way to settle the baby, instead of copying hers.', '["Try different holds — over the shoulder, along the forearm, chest to chest.", "Settle on the one that works for you, rather than copying hers exactly."]'::jsonb, 'Babies learn to be soothed in more than one way, and having your own method means she isn''t the only one who can settle them.'),
  ('name-what-you-re-feeling-m1', 'Say what you''re actually feeling in month one — out loud, to someone.', '["Notice if you feel useless, sidelined, terrified, or numb.", "Say it to someone — a friend, a brother, or her."]'::jsonb, 'Naming it stops it turning into distance or irritability — you are allowed to be finding this hard.'),
  ('sleep-when-you-can-m1', 'Take the naps — a functioning father beats a heroic one who collapses in month three.', '["Resist the urge to run on empty to prove something.", "Take the naps when they''re offered.", "Accept help that''s offered to you too, not just to her."]'::jsonb, 'A father who is functioning is worth more than one who is heroic now and falls apart in month three.'),
  ('if-you-are-the-one-struggling-m1', 'Paternal depression is real, affects one in ten fathers, and some thoughts need help the same day.', '["Watch for signs in yourself: irritability, withdrawing, working late to avoid coming home, drinking more, feeling flat or absent.", "Tell someone today — your partner, a friend, your doctor, or a helpline — if you''re thinking about ending your life or feel your family would be better off without you.", "Book a doctor''s appointment if the milder signs fit, since this is treatable."]'::jsonb, 'Coping is not the job — being here is the job, and men very often say nothing because asking for help feels like failing at the one thing they''re supposed to do.'),
  ('take-over-the-invisible-work-m1', 'Pick two whole areas of the invisible work and own them completely.', '["Identify the invisible work: remembering the vaccination date, noticing nappies running out, knowing which vest is clean.", "Pick two whole areas and own them completely, without being asked.", "Stop asking \"what do you need me to do\" — that still makes her the manager."]'::jsonb, 'Asking what she needs still makes her the manager of the household — owning whole areas outright is what actually lifts the load.'),
  ('set-up-the-feeding-station-m1', 'Set up wherever she feeds most — she may sit there for hours a day.', '["Find the spot where she feeds most.", "Stock it with water, snacks, a phone charger, muslins, nappies, a cushion, and the TV remote."]'::jsonb, 'She may sit there for hours a day — making that spot work well is a small act with an outsized return.'),
  ('say-the-thing-out-loud-m1', 'Tell her one specific thing you actually saw her do this week.', '["Notice one specific thing she did this week — for example, feeding through the night without complaint.", "Tell her plainly, in specific terms, not abstract praise about being a good mother."]'::jsonb, 'She is likely to feel invisible right now, and a specific thing you actually witnessed lands in a way general praise never does.'),
  ('two-minutes-not-about-the-baby-m1', 'Ask her one question a day that has nothing to do with the baby.', '["Once a day, ask her a question unrelated to the baby.", "Mean it, and listen to the answer for two minutes."]'::jsonb, 'In month one this is the whole relationship maintenance plan, and it''s enough.'),
  ('notice-what-changed-for-you-m1', 'Notice what has actually changed for you, not what should have.', '["Write or think through what has actually changed: freedom, sleep, identity, how people treat you, what you worry about."]'::jsonb, 'Fathers rarely get asked this and it goes unexamined for years — worth looking at honestly now.'),
  ('tell-work-early-m1', 'Have the conversation with your employer now, not week by week.', '["Talk to your employer about what the next few months look like: leave, flexibility, hours."]'::jsonb, 'Fathers who negotiate this early get better outcomes than those who improvise week by week and slowly disappoint everyone.'),
  ('go-to-the-6-week-check-m2', 'Go with her to the six-week check and take notes.', '["Go with her to the appointment.", "Take notes during the visit.", "Ask the questions she''s too tired to raise."]'::jsonb, 'She''s exhausted and may not absorb or ask everything, and hearing the answers directly means you''re not relying on a secondhand account of her own body.'),
  ('keep-watching-her-mood-m2', 'Keep watching for postpartum depression — it often surfaces around three to four months.', '["Watch for persistent low mood, loss of interest, hopelessness, difficulty bonding, rage or constant anxiety lasting more than two weeks.", "Ask her directly how she''s doing, and ask twice if the first answer is fine.", "Go with her to the doctor rather than suggesting she goes alone."]'::jsonb, 'This often surfaces around three to four months, exactly when the visitors have gone and everyone assumes you''ve both settled.'),
  ('protect-her-nap-m2', 'When she naps, the house and the baby are yours — don''t wake her for anything.', '["When she sleeps in the day, take over the house and the baby fully.", "Don''t wake her to ask where something is."]'::jsonb, 'This is the single most valuable two hours you can give her, and it''s easy to accidentally erode if you let yourself interrupt it.'),
  ('learn-what-feeding-actually-involves-m2', 'Learn how feeding actually works so you stop undermining it without meaning to.', '["If she''s breastfeeding, learn that cluster feeding in the evenings is normal, that frequent feeding builds supply rather than signalling failure, that soft breasts don''t mean low milk, and that pain almost always means a fixable latch problem.", "If she''s formula or mixed feeding, learn the preparation properly and take half the feeds.", "Either way, bring water, bring food, take the baby afterwards, and defend her from anyone offering opinions."]'::jsonb, 'Suggesting formula every time it gets hard is the single most undermining thing a well-meaning partner does — understanding how feeding actually works stops you doing it.'),
  ('take-bathtime-m2', 'Own bathtime completely, from running the bath to dressing them after.', '["Run the bath.", "Wash, dry and dress the baby yourself, start to finish."]'::jsonb, 'A ritual that is reliably yours builds your confidence and gives her a predictable window off duty.'),
  ('mirror-their-face-m2', 'Copy your baby''s expressions back to them — your first real conversation.', '["Hold your baby about 25cm from your face.", "Copy their expressions — open your mouth, stick your tongue out, widen your eyes."]'::jsonb, 'Around this age they start copying back — this is the first real conversation you''ll have with your child.'),
  ('wear-your-baby-m2', 'Get a carrier and use it for everyday tasks.', '["Get a baby carrier.", "Wear the baby while you walk to the shops, do the washing up, or take a phone call."]'::jsonb, 'It''s practical, it settles the baby, and it builds a physical closeness that doesn''t depend on feeding.'),
  ('keep-one-thing-that-s-yours-m2', 'Keep one protected thing that''s just yours from before the baby.', '["Pick one activity from before the baby — football, gym, a friend, a hobby.", "Protect that one thing, even if it''s not much time."]'::jsonb, 'Fathers who lose everything of their own tend to become resentful around month five, and it comes out sideways.'),
  ('talk-to-another-father-m2', 'Find one father a year or two ahead and talk to him honestly.', '["Find one man who''s a year or two ahead of you.", "Talk to him honestly about what''s hard, not just swap advice."]'::jsonb, 'Most fathers have no one they discuss this with, and the isolation is real even when nobody names it.'),
  ('own-the-admin-m2', 'Take all the admin — it doesn''t require breastfeeding.', '["Handle birth registration, insurance, paediatrician appointments, the vaccination schedule, and bank and nominee updates."]'::jsonb, 'It''s tedious work that doesn''t require breastfeeding, so there''s no reason it shouldn''t be yours.'),
  ('cook-or-arrange-the-food-m2', 'Either cook or organise the food — ordering in every night doesn''t last.', '["Decide whether you''ll cook or organise it — batch meals, a cook, or a reliable rotation.", "Set the system up so it runs without a daily decision."]'::jsonb, 'Postpartum nutrition genuinely affects her recovery and milk supply, and ''we''ll order something'' stops being sustainable fast.'),
  ('start-the-nightly-five-minutes-m2', 'Extend the daily check-in to five minutes, and be the one who starts it.', '["Each night, share one good thing and one hard thing from the day.", "Start it yourself every time, so it''s never one more thing she has to organise.", "Go first and be honest about your own hard thing.", "When she shares hers, just listen — no fixing, no advice unless she asks."]'::jsonb, 'Starting it yourself every night means it never becomes one more thing she has to organise.'),
  ('ask-what-she-actually-wants-m2', 'Ask whether she wants you to solve it or just listen.', '["When she describes something difficult, ask directly: do you want help solving this, or do you want me to just listen?", "Do whichever she says."]'::jsonb, 'Getting this wrong is the most common source of pointless friction in the first year, and asking takes three seconds.'),
  ('stand-between-not-aside-m2', 'Manage your own parents'' advice and opinions — that''s your job, not hers.', '["Take the conversation with your own parents about outdated or conflicting advice yourself.", "Have it privately and warmly, outside the moment, framed around the doctor rather than who''s right.", "Step in immediately if a disagreement about the baby starts playing out in front of her."]'::jsonb, 'She cannot push back on your mother without it costing her, and if she has to do it alone she will pay for it for years — this single thing predicts how she remembers this year more than almost anything else you do.'),
  ('talk-about-not-having-another-yet-m2', 'Raise postpartum contraception at the six-week check — don''t leave it to her.', '["Remember that fertility can return before her periods do, often earlier than either of you expects.", "Raise contraception at the six-week check together.", "Get actual medical advice on what is safe alongside breastfeeding."]'::jsonb, 'A second pregnancy very soon after birth carries real health risks for her, particularly after a caesarean — raising it together beats the alternative of leaving it to chance.'),
  ('rethink-what-a-father-does-m2', 'Decide deliberately what you want to do differently from the template you inherited.', '["Notice the template you inherited: providing and present, but not hands-on daily.", "Decide deliberately what you want to do differently, rather than defaulting to it."]'::jsonb, 'That template isn''t a criticism of your father, it''s just what the era looked like — deciding deliberately is how you choose your own.'),
  ('push-for-physio-if-she-needs-it-m3', 'If she has leaking, heaviness, back pain or a tummy gap, book the physio.', '["Ask if she has leaking, heaviness, back pain, painful intercourse, or a tummy gap.", "Book a women''s health physiotherapist if so.", "Go with her."]'::jsonb, 'Most women don''t go because they assume it''s normal or don''t want the fuss — a physiotherapist treats all of it.'),
  ('give-her-a-real-break-m3', 'Give her three hours completely off, not an hour with you in the next room.', '["Take the baby out for three hours, or send her out with no set return time.", "Make sure she genuinely isn''t on call during it."]'::jsonb, 'The mental load only lifts when she genuinely isn''t on call.'),
  ('learn-her-body-signals-m3', 'Learn her tells, so she doesn''t have to explain she''s struggling.', '["Learn her tells for pain or struggle: how she holds herself, going quiet, getting short-tempered.", "Name it gently when you see it — \"You seem like you''re in pain, what''s going on?\""]'::jsonb, 'Being seen without having to explain is a genuine relief for her.'),
  ('get-on-the-floor-m3', 'Get down to their level during tummy time — it works far better.', '["Lie down opposite your baby during tummy time.", "Make noise and be interesting to look at."]'::jsonb, 'This is also where you''ll notice their development happening — the day they push up higher, the day they roll.'),
  ('take-over-one-full-routine-m3', 'Pick one daily routine and own it completely and consistently.', '["Pick one daily routine — morning wake-up, bedtime, or the afternoon walk.", "Own it completely and consistently."]'::jsonb, 'Predictable presence from you builds a distinct relationship with your child that isn''t just backup for her.'),
  ('read-to-them-m3', 'Read to them ten minutes a day — any book at all.', '["Read any book for ten minutes, every day."]'::jsonb, 'They''re not following the story — they''re absorbing your voice, rhythm and attention, and this is one of the easiest fatherhood habits to start early and hardest to start late.'),
  ('check-in-with-yourself-m3', 'Check yourself for paternal depression — it peaks around now.', '["Watch for irritability, withdrawal, working late to avoid home, drinking more, or feeling nothing.", "Talk to a doctor if any of this fits."]'::jsonb, 'Paternal depression affects roughly one in ten fathers and peaks between three and six months — it''s treatable and more common than anyone admits.'),
  ('move-your-body-m3', 'Move your body for twenty minutes, three times a week.', '["Do twenty minutes of any physical activity, three times a week."]'::jsonb, 'Your energy directly affects how present you can be, and fathers lose fitness at almost the same rate as mothers in year one — nobody tracks it, but it matters.'),
  ('run-the-house-for-a-weekend-m3', 'Run the whole house for a weekend — meals, cleaning, shopping, baby, laundry.', '["Take a full weekend and run everything yourself: meals, cleaning, shopping, the baby, laundry."]'::jsonb, 'This is a genuine test of whether you actually know how the household works — most fathers discover several things they didn''t know were happening.'),
  ('make-time-for-the-real-conversation-m3', 'Set aside twenty minutes to talk about the two of you, not logistics.', '["Pick a time that isn''t 11pm, and arrange the baby so you won''t be interrupted.", "Ask the first question yourself.", "Hear what''s been hardest for her before you share what''s been hardest for you."]'::jsonb, 'Most couples haven''t had this conversation by now — having it imperfectly beats not having it at all.'),
  ('ask-about-intimacy-without-pressure-m3', 'Ask how she''s feeling about intimacy, with no expectation attached.', '["Ask how she''s feeling about physical intimacy.", "Make clear there''s no expectation attached to the question.", "Listen to the answer."]'::jsonb, 'Not raising it at all reads as either indifference or pressure building — raising it well is neither.'),
  ('define-the-father-you-want-to-be-m3', 'Write down five things you want your child to say about you at thirty.', '["Write down five things you want your child to say about you when they''re thirty.", "Look honestly at your last month against that list."]'::jsonb, 'The gap between the two is your actual to-do list, and it''s usually about time and attention rather than money.'),
  ('watch-for-month-4-mood-dip-m4', 'PPD often peaks around now, right when everyone else has stopped asking.', '["Ask her directly how she''s doing.", "Ask again if the first answer is just ''fine''."]'::jsonb, 'The visitors have gone and the exhaustion has accumulated right when everyone else has stopped asking — your asking twice matters.'),
  ('back-her-return-to-work-m4', 'If she''s returning to work, the logistics are not her problem alone.', '["Agree in detail now: childcare handover, sick-day cover, who does drop-off, whose meeting moves when the baby has a fever."]'::jsonb, 'Agreeing it now beats discovering later that the default is always her.'),
  ('guard-her-exercise-time-m4', 'Guard her exercise slot the way you''d guard a work meeting.', '["Protect her exercise time on the calendar.", "Treat it as rehabilitation, not leisure, when a fussy afternoon threatens it."]'::jsonb, 'It''s rehabilitation of a body that was structurally altered, and it''s the thing most easily lost to a fussy afternoon.'),
  ('play-the-anticipation-game-m4', 'Do the same silly thing three times, then pause and watch them predict it.', '["Pick a silly, repeatable move — peek-a-boo, a telegraphed tickle, a sound you build up to.", "Do it three times.", "Pause before the fourth and watch for the grin of anticipation."]'::jsonb, 'That grin before you do it again is their brain predicting the future — a real cognitive milestone dressed up as a game.'),
  ('do-the-solo-outing-m4', 'Take the baby out alone — no mother present, no backup.', '["Take the baby out by yourself — a walk, a shop, a relative''s house.", "Do it with no backup."]'::jsonb, 'It''s the fastest way to build genuine confidence, and it makes clear to everyone, including you, that you''re a parent, not an assistant.'),
  ('copy-their-sounds-back-m4', 'Babble the same sound back to them, then wait for their turn.', '["When they babble, babble the same sound back.", "Pause and wait for them to respond."]'::jsonb, 'This turn-taking is how conversation is learned, and doing it with you means they''re getting the pattern from two different voices and rhythms.'),
  ('audit-your-own-sleep-m4', 'Track your own sleep for a week — your deficit counts too.', '["Track your sleep for a week: total hours, longest stretch, interruptions."]'::jsonb, 'Chronic sleep deprivation affects your patience, driving and work regardless of who''s breastfeeding, and fathers routinely assume theirs doesn''t count.'),
  ('get-your-own-health-checked-m4', 'Book the health check you''ve been putting off.', '["Book a check for blood pressure, weight, and bloods."]'::jsonb, 'Fathers commonly skip their own health entirely in the first year while attending every paediatric appointment — this is the one you''ve been putting off.'),
  ('own-the-calendar-m4', 'Own the entire calendar — every appointment, vaccination and reminder.', '["Take over every appointment, vaccination, review and reminder.", "Keep it yours, not shared."]'::jsonb, 'The mental load of remembering is heavier than the doing, and this is the cleanest way to lift a real chunk of it.'),
  ('name-one-thing-she-did-today-m4', 'Add a specific thing you noticed and appreciated about her that day.', '["Each night, add a third element to your check-in: one specific thing you noticed and appreciated about her that day.", "Keep it observed and specific, not general praise."]'::jsonb, '"You got him to sleep when I couldn''t" lands — "you''re a great mum" does not.'),
  ('plan-the-first-date-at-home-m4', 'Plan a date at home yourself, so she doesn''t have to organise it.', '["Pick the evening and make sure the baby is asleep or covered.", "Set the table and sort the food.", "Put phones away for ninety minutes."]'::jsonb, 'You don''t need to leave the house for it to count — you need attention and intention, and doing the planning yourself is the point.'),
  ('notice-where-your-time-goes-m4', 'Track one week honestly: work, commute, baby, chores, phone.', '["Track one week honestly: work, commute, time with the baby, chores, your own time, phone."]'::jsonb, 'Most fathers find the phone number is large and the baby number smaller than assumed — the data is uncomfortable and useful.'),
  ('ask-about-her-body-honestly-m5', 'Ask specifically about leaking, pain, back pain, heaviness, a tummy gap.', '["Ask her specifically: any leaking, pain during sex, back pain, heaviness, or a tummy gap that hasn''t closed?"]'::jsonb, 'These are common, treatable, and almost never volunteered — asking directly gives her permission to answer honestly.'),
  ('take-a-night-fully-m5', 'Give her one fully uninterrupted night a week.', '["Once a week, send her to bed early.", "Make sure she hears nothing until morning.", "Do the whole night yourself if bottle-feeding is possible."]'::jsonb, 'One genuinely uninterrupted night a week measurably changes mood and functioning.'),
  ('follow-their-lead-m5', 'Fifteen minutes on the floor doing nothing except responding.', '["Get on the floor with your baby for fifteen minutes.", "Let them choose what happens — no teaching, no directing, no phone.", "Just respond to what they do."]'::jsonb, 'This is the single most evidence-backed thing you can do for their development, and it asks less of you than any structured activity.'),
  ('be-the-physical-one-m5', 'Roughhouse with them — controlled, safe, at their level.', '["Lift, swing, roll or bounce them in controlled, safe play."]'::jsonb, 'This builds body confidence, risk judgement, and emotional regulation through excitement and recovery — fathers playing physically is genuinely valuable, not just rough.'),
  ('protect-one-evening-m5', 'Protect one evening a week that''s entirely yours, not earned each time.', '["Fix one evening a week as yours, not negotiated each time.", "Make sure she has the exact equivalent."]'::jsonb, 'Couples who formalise this stop keeping score, and the scorekeeping is what causes the damage.'),
  ('split-the-load-honestly-m5', 'Write down separately what each of you does in a week, then compare.', '["Each write down separately everything you do in a week, including the invisible noticing and remembering.", "Compare the two lists honestly."]'::jsonb, 'The comparison matters more than the fix, because most imbalance is invisible to the person benefiting from it.'),
  ('keep-the-weekly-twenty-minutes-m5', 'Make the weekly twenty-minute check-in a fixture, and own the calendar for it.', '["Set a same weekly slot for a twenty-minute check-in.", "Open by asking how she''s doing and what she needs this week, before logistics.", "Be straight about how you''re doing too."]'::jsonb, 'It''s a habit, not a crisis meeting — owning the calendar slot is your part of keeping it alive.'),
  ('line-up-something-to-look-forward-to-m5', 'Plan one thing three to six months out that you''d both enjoy.', '["Pick something three to six months out — a trip, a visit to her family, a home project.", "Do the legwork yourself: dates, bookings, baby arrangements.", "Check the plan with her rather than handing her a to-do list."]'::jsonb, 'Having a future to point at changes how the present feels.'),
  ('talk-to-your-own-father-m5', 'Ask your own father what fatherhood was actually like for him.', '["Ask him what he found hard, what he''d do differently, and what he wishes he''d known."]'::jsonb, 'Most men have never had this conversation, and it tends to be more revealing than expected — it often changes how you read your own childhood.'),
  ('support-the-solids-transition-m6', 'Learn solids properly alongside her, and do half the meals.', '["Learn the real anxieties around solids: allergies, choking, whether they''re eating enough.", "Do half the meals yourself."]'::jsonb, 'Shared knowledge halves the worry that comes with this transition.'),
  ('notice-the-six-month-wall-m6', 'Watch for the six-month wall — a common low point for both of you.', '["Watch for it in her: the novelty gone, sleep still broken, support evaporated.", "Watch for it in yourself too.", "Name it as a known phase, not a personal failure, when you see it."]'::jsonb, 'Naming it as a known phase rather than a personal failure helps both of you get through it.'),
  ('do-the-solids-mess-m6', 'Own weaning meals — the prep, the mess, and the clean-up.', '["Prepare the weaning meals.", "Handle the mess and the clean-up yourself."]'::jsonb, 'It''s exactly the kind of work that quietly defaults to mothers if nobody claims it.'),
  ('hide-and-come-back-m6', 'Hide and reappear — they''re learning you leaving doesn''t mean you''re gone.', '["Hide behind your hands, a cushion, or a door.", "Reappear, and repeat."]'::jsonb, 'Their delight is a prediction being confirmed, and it''s quietly how they learn that you leaving doesn''t mean you''re gone.'),
  ('six-month-self-check-m6', 'Check on yourself the way you''d check on her — this is when it often surfaces.', '["Check for withdrawing, irritability, working late to avoid home, drinking more, or feeling flat.", "Ask for help if any of it fits."]'::jsonb, 'Paternal depression frequently surfaces around now, and asking for help is not a failure of anything.'),
  ('half-the-mental-load-m6', 'Take half the noticing, not just half the tasks.', '["Start noticing yourself: whether nappies are running low, whether bigger clothes are needed, whether a vaccination is due."]'::jsonb, 'If she''s still the one noticing and you''re the one doing, the load isn''t actually shared.'),
  ('bring-a-non-baby-topic-m6', 'Bring her a non-baby topic to talk about, every day.', '["Each day, bring up something unrelated to the baby — a film, an idea, a plan, a trivial argument.", "Make it your job to come with the topic."]'::jsonb, 'You were two people with opinions before this, and that doesn''t maintain itself — coming with the topic is your part.'),
  ('six-month-fatherhood-review-m6', 'Review honestly what kind of father you''ve actually been for six months.', '["Reflect on what actually happened over six months, not what you intended.", "Note what surprised you, what you''ve avoided, and what you want to change next."]'::jsonb, 'This is about what happened, not what you meant to happen.'),
  ('back-her-physical-rebuild-m7', 'Cover the time for her physical rebuild without making it a negotiation.', '["Cover the time for her to return to running, gym or sport.", "Do it as a given, not a favour or a negotiation."]'::jsonb, 'This is when many women give up on their own recovery because the logistics get too hard to keep arranging.'),
  ('handle-separation-anxiety-m7', 'Keep goodbyes short and consistent when separation anxiety starts.', '["Keep goodbyes short, consistent and warm.", "Say the same thing every time.", "Always come back when you said you would."]'::jsonb, 'This is a developmental milestone, not rejection — long drawn-out goodbyes actually make it worse.'),
  ('chase-and-be-chased-m7', 'Chase them on all fours — cardio for you, a foundational game for them.', '["Chase your baby on all fours.", "Let them escape, then chase again."]'::jsonb, 'It''s a genuine cardio session for you and a foundational game for them.'),
  ('rebuild-one-friendship-m7', 'Pick one friend and make actual contact, not a group text.', '["Pick one friendship that''s slipped.", "Make contact and arrange an actual meeting."]'::jsonb, 'Male friendships tend to quietly collapse in the first year of fatherhood and are hard to restart later.'),
  ('check-your-own-habits-m7', 'Look honestly at your drinking, phone use, sleep and work — pick one to fix.', '["Look honestly at your drinking, phone use, sleep, and how much you''re working.", "Pick whichever has slipped furthest.", "Correct it now, while it''s still a habit rather than a fixture."]'::jsonb, 'These drift in the first year, and the drift is easy to miss because everything feels temporary.'),
  ('take-over-a-whole-domain-m7', 'Pick an entire area of family life and own it completely, including the noticing.', '["Pick one entire domain — health appointments, or food and shopping, or clothes and sizes.", "Own the whole thing, including the noticing and the remembering, not just the tasks."]'::jsonb, 'The mental load is the part that exhausts, and it only lifts when someone else genuinely holds it rather than helping with it.'),
  ('arrange-the-first-night-out-m7', 'Arrange the first night out yourself, so she can simply come.', '["Arrange cover for two or three hours.", "Sort the babysitter, the timing and the plan yourself.", "Let her come without having to organise anything.", "If she wants to call home or come back early, let that be fine."]'::jsonb, 'The first one is often harder emotionally than expected, especially for her — that''s worth noticing, not pushing past.'),
  ('notice-what-you-have-learned-m7', 'Notice what you can do now that you couldn''t seven months ago.', '["Take ten minutes to list what you can do now that you couldn''t before."]'::jsonb, 'Competence you haven''t noticed doesn''t build confidence, and fathers rarely acknowledge their own progress.'),
  ('ask-about-the-tummy-gap-m8', 'Ask whether she''s had her tummy checked for a muscle gap.', '["Ask whether she''s had her tummy checked for a gap between the muscles, back pain, or a bulging belly when she strains.", "Encourage the appointment if so.", "Cover the childcare so she can go."]'::jsonb, 'Physiotherapy usually resolves this where time alone often does not.'),
  ('build-a-safe-climbing-course-m8', 'Build a safe climbing course and let them wobble and fall under your watch.', '["Set up cushions, a low sofa, a mattress on the floor.", "Let them climb, wobble and fall safely while you spot them."]'::jsonb, 'Children need someone who lets them attempt slightly hard things, and fathers are often better at tolerating this than mothers.'),
  ('protect-your-own-sleep-too-m8', 'Agree one night a week where you sleep properly and she covers.', '["Agree one night a week where you sleep fully and she covers.", "Cover one night for her in exchange."]'::jsonb, 'Neither of you functioning is worse for the baby than one of you rested, and chronic sleep loss affects your patience, driving and judgement regardless of who''s breastfeeding.'),
  ('baby-proof-properly-m8', 'Do a proper baby-proofing sweep at their height, before the first accident.', '["Get on your hands and knees at their height.", "Check sockets, corners, cords, stairs, cleaning products, water buckets."]'::jsonb, 'Do it before the first accident, not after.'),
  ('learn-the-baby-red-flags-m8', 'Know the baby red flags yourself — don''t leave this knowledge only with her.', '["Learn the red flags: fever under three months, difficulty or fast breathing, a rash that doesn''t fade under a glass, unusual floppiness or drowsiness, refusing feeds repeatedly, fewer wet nappies, or an unusual cry.", "Know the nearest hospital with a paediatric emergency unit.", "Save your paediatrician''s number."]'::jsonb, 'Do not leave this knowledge only with her — you need to be able to act on it too.'),
  ('write-her-a-note-m8', 'Write her a short handwritten note about what you''ve noticed her do.', '["Write three sentences on paper about what you''ve noticed her do this year."]'::jsonb, 'Handwritten is different from spoken — it gets kept and reread on bad days.'),
  ('raise-the-next-year-conversation-m8', 'Start the conversation about the next twelve months — ask about her plans first.', '["Start a conversation about twelve months ahead: work, another child, where you''ll live, what family life should feel like.", "Ask about her plans first, especially her work."]'::jsonb, 'Her plans are the ones most often quietly shelved after a baby — being partners in a plan is different from being partners in a routine.'),
  ('ask-what-she-has-given-up-m8', 'Ask her directly what she''s lost this year that she hasn''t talked about.', '["Ask her directly what she''s lost this year — career momentum, friendships, her body feeling like hers, time alone, spontaneity.", "Just listen, without defending, solving, or comparing to what you''ve given up."]'::jsonb, 'Most women find nobody has asked them this — let what she says simply be true.'),
  ('nine-month-honest-check-m9', 'Ask her how she actually is, nine months in — body, mood, work, us.', '["Ask directly how she''s doing: body, mood, work, the relationship."]'::jsonb, 'Nine months is when fatigue is deepest and everyone assumes you''ve both figured it out — asking properly now matters more than it did at month two.'),
  ('be-there-for-first-steps-m9', 'Be present for the attempts at walking, not just the milestone itself.', '["Make time to be present for the pulling up, the cruising, the wobbly attempts — not just the eventual first steps."]'::jsonb, 'Fathers often miss these to work and then regret it in a way they didn''t expect.'),
  ('own-bedtime-fully-m9', 'Take the entire bedtime routine several nights a week.', '["Run the whole bedtime routine several nights a week: bath, milk, book, settling."]'::jsonb, 'It''s the highest-value bonding window of the day and the one most often ceded to mothers by default.'),
  ('set-a-physical-goal-m9', 'Pick a physical goal with a date on it.', '["Pick a specific goal with a date attached — a distance, a weight, a game you want to play again."]'::jsonb, 'Fathers'' fitness declines quietly across the first year, and a goal reverses it more reliably than intention does.'),
  ('own-the-money-conversation-m9', 'Look at the finances properly together, nine months in.', '["Review together what has changed financially, what childcare will cost, what happens if one of you reduces hours, and whether there''s a cushion."]'::jsonb, 'Arguments about money are usually about not having looked at it rather than about the numbers themselves.'),
  ('protect-her-alone-time-as-well-as-yours-m9', 'Agree how much alone time each of you gets each week, and check hers is as real as yours.', '["Agree how much time each of you gets to yourselves weekly, when, and how it''s protected.", "Check that her time is as real as yours.", "Cover the baby to make her time actually possible."]'::jsonb, 'It''s easy for one person''s time to survive while the other''s quietly disappears — most couples only have this conversation once someone has reached breaking point.'),
  ('do-the-household-skills-you-avoid-m9', 'Pick the domestic skill you''ve avoided learning, and learn it now.', '["Identify the domestic area you''ve quietly never learned — cooking a full meal, knowing where things are kept, laundry, handling domestic help.", "Learn it now."]'::jsonb, 'Competence here is not a favour to her — it''s the difference between being a partner and being assisted.'),
  ('push-the-physio-question-again-m10', 'If anything from her recovery is unresolved, book the physio now.', '["Check whether leaking, pain during sex, back pain, or the tummy gap is still unresolved.", "Book the appointment if so."]'::jsonb, 'Ten months is not too late and it will not fix itself — many women have quietly accepted these as permanent by now.'),
  ('set-up-the-cruising-circuit-m10', 'Set up a safe furniture loop for cruising, and match their energy.', '["Arrange a safe loop of sofa, table and chair.", "Move alongside them as they cruise, encouraging it with matched energy."]'::jsonb, 'This is peak physical development and your enthusiasm genuinely fuels it.'),
  ('eat-together-m10', 'Sit down and eat the same meal together, a few times a week.', '["Sit down and eat the same meal at the same time, at least a few times a week."]'::jsonb, 'Family mealtimes are the richest language environment a child gets, and this is how food habits and table behaviour actually transfer.'),
  ('look-after-your-own-body-m10', 'Book the check-up you''ve been putting off, and restart one physical thing.', '["Book the health check-up you''ve been putting off.", "Pick one physical thing to restart."]'::jsonb, 'Your energy directly determines how present you''re able to be, and fathers routinely ignore their own health while attending every paediatric appointment.'),
  ('audit-the-load-again-m10', 'Redo the load audit from month 5 — it quietly redistributes over time.', '["Both write down separately everything you do in a week, including the invisible noticing and remembering.", "Compare the lists."]'::jsonb, 'The load quietly redistributes over time, usually not in her favour, which is why this is worth redoing.'),
  ('keep-the-monthly-date-in-your-calendar-m10', 'Keep a monthly date as a fixture, arranged by you, regardless of how things are going.', '["Arrange two to three hours out once a month: book cover, choose the place, make the plan."]'::jsonb, 'Couples who protect this tend to be the ones still doing well at year three — it''s a fixture, not a treat for calm weeks.'),
  ('handle-the-second-baby-question-m10', 'Agree a line for the second-baby question, and make sure it never lands on her alone.', '["Agree a line with her for anyone who asks about a second baby.", "Use it whenever the question comes up, and don''t let it land on her alone.", "If you''re actually discussing it, do it properly and privately, involving her doctor on spacing after a caesarean."]'::jsonb, 'Her body needs recovery time and her feelings about it may be very different from yours — this deserves a private, proper conversation, not a public one.'),
  ('ask-what-kind-of-father-they-see-m10', 'Think about what they''re learning from watching how you speak to their mother.', '["Sit with the fact that your baby knows exactly who you are.", "Think honestly about what they''re learning from watching you, particularly how you speak to their mother and handle frustration."]'::jsonb, 'That is the curriculum, and it started already — you have become a specific person to them, not a general one.'),
  ('ask-how-she-is-properly-m11', 'Ask how she actually is — everyone else has stopped asking by now.', '["Sit down and ask how she actually is: body, mood, work, friendships, how she feels about herself.", "Ask again if the first answer is just fine."]'::jsonb, 'This is the month where the assumption that you''ve both figured it out is strongest and least accurate.'),
  ('let-them-choose-the-book-m11', 'Let them pick the book, even the fortieth time running.', '["Keep books at their height.", "Let them pick one and bring it to you.", "Read whatever they choose, without redirecting."]'::jsonb, 'The same book forty times is not boredom — it''s how learning actually works from the inside.'),
  ('take-stock-of-yourself-m11', 'Compare how you''re sleeping, drinking, moving and feeling to a year ago.', '["Compare your sleep, drinking, movement and mood to a year ago.", "Name one thing that''s declined and name one thing to reclaim."]'::jsonb, 'Fathers often reach the first birthday having quietly lost fitness, friendships and interests without ever deciding to.'),
  ('plan-the-second-year-m11', 'Plan the second year deliberately, instead of drifting into it.', '["Look ahead deliberately: childcare, work patterns, any changes either of you wants, travel, where you want to live.", "Decide it together rather than letting it drift."]'::jsonb, 'The first year is survived; the second is chosen — choosing it together is what stops resentment building.'),
  ('write-her-your-year-one-letter-m11', 'Write her a letter about this year, and write yours first.', '["Write a letter covering what you appreciated about her as a partner, admired about her as a parent, and want for next year.", "Suggest exchanging letters, and write yours first."]'::jsonb, 'Writing yours first means she isn''t the one doing the emotional work of starting it.'),
  ('open-the-conversation-about-closeness-m11', 'Open an honest conversation about intimacy — what''s returned, what hasn''t.', '["Raise the conversation gently, without pressure or complaint.", "Ask what''s returned, what hasn''t, and what each of you needs.", "Listen properly, especially if pain, exhaustion or body image is part of her answer."]'::jsonb, 'Many couples let this go unspoken for a year and then find the distance harder to close than the original problem.'),
  ('write-to-your-child-m11', 'Write a letter to your baby about this first year, and seal it.', '["Write a letter to your baby: what you noticed, what surprised you, what you hope for them, what becoming their father did to you.", "Seal it to open on a future birthday."]'::jsonb, 'This becomes the most valuable thing you write, read years from now on a birthday that means more by then.'),
  ('ask-about-her-year-of-recovery-m12', 'Ask whether anything from her recovery is still bothering her, a year on.', '["Ask whether her pelvic floor, back, tummy gap, scar, pain or mood is still an issue.", "Book the appointment yourself if anything is unresolved.", "Cover the childcare."]'::jsonb, 'She has probably put her own health behind everyone else''s for twelve months — booking it yourself beats suggesting she does.'),
  ('first-birthday-marked-properly-m12', 'Design the first birthday for the adults as much as the child.', '["Plan a photo, a meal, something read aloud.", "Mark it deliberately as something for the adults too, not just the child."]'::jsonb, 'You raised a person through their most fragile year — that''s worth marking deliberately.'),
  ('tell-them-the-year-s-story-m12', 'Go through the year''s photos with them and tell the story out loud.', '["Sit with them and go through the year''s photos.", "Name people and places and tell the story out loud."]'::jsonb, 'They won''t understand yet, but telling your child their own story is a habit worth having, and it starts now.'),
  ('full-year-self-review-m12', 'Review a full year: sleep, drinking, movement, feeling — fix one thing.', '["Review a full year of sleep, drinking, movement and feeling.", "Pick one thing that''s declined.", "Fix it in the next three months."]'::jsonb, 'This is the thing you''ve been ignoring because it seemed less important than everything else.'),
  ('split-the-second-year-fairly-m12', 'Decide the next year''s load deliberately, instead of letting defaults set it.', '["Decide deliberately who does drop-off, who takes the day off when the baby is ill, and whose career absorbs the disruption."]'::jsonb, 'Defaults are where inequality lives, and after twelve months they''re set unless you actively reset them.'),
  ('set-up-the-year-one-relationship-review-m12', 'Set up a ninety-minute relationship review before the first birthday.', '["Arrange ninety minutes without the baby: the cover, the time, the questions.", "Ask what was hardest this year, what you''re proud of, and what to protect in year two.", "Let her answer first."]'::jsonb, 'Setting it up yourself means it''s one less thing for her to organise.'),
  ('keep-running-the-three-habits-m12', 'Agree which habits actually helped, and take responsibility for keeping them going.', '["Review the year''s habits: the nightly five minutes, the weekly twenty, the monthly date, the solo evenings.", "Agree which ones actually helped.", "Take responsibility for keeping them going in year two."]'::jsonb, 'This is yours to maintain, rather than leaving it to her to notice when they lapse.'),
  ('ask-her-what-she-needs-back-m12', 'Ask her what she wants back in year two, and make one of them actually happen.', '["Ask her what she wants back in year two — her exercise slot, a weekend away, a course, evenings with friends, career time.", "Arrange one of them as a fact, not a favour."]'::jsonb, 'She has spent a year giving things up — arranging it as a fact, not a favour, is what makes it real.'),
  ('the-father-you-ve-become-m12', 'Reread your month-three intentions and compare them honestly to the year you had.', '["Reread what you wrote in month three about the father you wanted to be.", "Compare it honestly to the year you actually had.", "Write the version for year two."]'::jsonb, 'This isn''t to feel bad — it''s to see clearly, and the gap narrows if you keep looking at it.'),
  ('decide-what-work-looks-like-now-m12', 'Decide deliberately what role work plays now, rather than defaulting.', '["Decide deliberately: hours, travel, whether you''re home for bedtime, what you''d trade."]'::jsonb, 'Fathers who never make this decision consciously usually find it''s been made for them.'),
  ('do-all-the-lifting-m1', 'For six weeks, she lifts nothing heavier than the baby — you carry the rest.', '["Carry everything heavier than the baby: laundry baskets, shopping, the toddler, the car seat.", "Enforce the no-lifting rule kindly, without making her ask."]'::jsonb, 'This is the most-ignored surgical instruction and the most common cause of wound complications.'),
  ('learn-the-wound-signs-m1', 'Check her incision daily with her, and know what''s not normal.', '["Check the incision daily together.", "Know what''s normal: bruising, numbness, itching.", "Know what''s not: spreading redness, warmth, swelling, discharge, foul smell, separating edges, or fever above 38°C."]'::jsonb, 'Surgical wound infections escalate quickly and are far easier to treat early.'),
  ('help-her-out-of-bed-m1', 'Learn the roll-to-side way she needs to get out of bed, and help her do it.', '["Learn the movement: roll to her side, then push up sideways rather than sitting straight up.", "Help her do it, especially at night, for the first two weeks."]'::jsonb, 'Sitting straight up loads the incision directly, so helping her do it the right way genuinely matters.'),
  ('bring-the-baby-to-her-m1', 'Bring the baby to her for every feed and pick-up, without being called.', '["Bring the baby to her for every feed, pick-up and settle.", "Take the baby back afterward.", "Anticipate it rather than waiting to be called."]'::jsonb, 'She physically cannot bend and lift the baby from a cot or the floor for weeks.'),
  ('keep-a-pillow-everywhere-m1', 'Put a firm pillow everywhere she sits, for coughs, sneezes and laughs.', '["Put a firm pillow wherever she sits: sofa, bed, car, feeding chair.", "Remind her to hold it against the incision when she coughs, sneezes or laughs."]'::jsonb, 'Unsupported coughing in the early weeks genuinely hurts and strains the wound.'),
  ('take-over-driving-m1', 'Take over all the driving for about six weeks.', '["Handle all the driving for around six weeks.", "Plan logistics so she isn''t stranded or tempted to drive, and appointments stay manageable."]'::jsonb, 'Emergency braking loads the incision, and insurance often won''t cover her driving in this window.'),
  ('understand-the-slower-timeline-m2', 'Tell her out loud: six weeks is cleared, not healed.', '["Learn that the abdominal wall keeps remodelling for a year or more after six weeks.", "Say this to her directly, since it lands better from you than from the internet."]'::jsonb, 'She may compare herself unfavourably to friends who delivered vaginally, and hearing from you that six weeks is cleared, not healed, matters.'),
  ('back-the-scar-massage-habit-m3', 'Back her daily scar massage habit — easy to skip, hard to undo later.', '["Remind her about daily scar massage without nagging.", "Take the baby so she has five uninterrupted minutes to do it."]'::jsonb, 'This genuinely prevents the adhesions that cause pulling, restricted movement and back pain years later, and it''s easy to skip because nothing hurts yet.'),
  ('know-about-the-numbness-m4', 'Know that numbness above the scar is common, even though nobody warns women about it.', '["Learn that numbness above the scar is extremely common and can persist a year or longer.", "Tell her it''s expected, so it feels less frightening."]'::jsonb, 'It can feel distressing, like part of her body isn''t hers, and knowing it''s expected makes it much less frightening.'),
  ('keep-making-time-for-her-scar-care-m5', 'Keep making the five minutes happen for her daily scar care.', '["Take the baby at the same time every day so she can do scar massage undisturbed.", "Encourage a physio visit if she mentions tightness, pulling, or numbness.", "Cover the childcare for that appointment."]'::jsonb, 'The daily massage that keeps the scar soft is one of the first things to get dropped once life gets busy — your part is keeping it happening.'),
  ('watch-for-the-scar-back-pain-link-m6', 'If she has persistent back pain, the scar may be the cause.', '["Watch for persistent back pain.", "Mention the scar as a likely cause and suggest a physio."]'::jsonb, 'C-section scar tightness pulls the pelvis forward and causes back pain that seems completely unrelated to the surgery — most people never make the connection.'),
  ('support-the-slower-core-rebuild-m7', 'Her core rebuild is genuinely slower after surgery — cover the time for it.', '["Cover the time for physio-led core rebuilding.", "Avoid comparing her progress to anyone else''s."]'::jsonb, 'Her abdominal muscles were surgically cut and the nerves disrupted, so this is genuinely slower, not a sign she''s behind.'),
  ('cover-the-impact-check-m9', 'Cover the childcare so she can safely test her readiness for running.', '["Cover the childcare so she can test running or jumping.", "Watch for pulling at the scar, doming along the midline, or back pain afterward as signs to stop.", "Get her to an assessment if any of those show up."]'::jsonb, 'Her abdominal wall needs to tolerate the load as well as the pelvic floor before she returns to impact.'),
  ('ask-about-the-numb-patch-m11', 'Ask whether the numb patch above her scar is still there, and that it''s expected.', '["Ask whether the numbness above her scar is still there.", "Tell her it''s expected and common.", "Mention that desensitisation work with a physio helps if it''s bothering her."]'::jsonb, 'This can feel genuinely distressing, as though part of her body isn''t hers, and almost nobody warns women about it.'),
  ('cover-the-twelve-month-scar-check-m12', 'Make sure her scar gets a proper look around the first birthday.', '["Ask whether the scar still feels tight, raised or pulled.", "Book the appointment yourself if it does.", "Go with her."]'::jsonb, 'Full healing takes about two years, so a year is a checkpoint, not a deadline — your job is making sure it doesn''t get skipped in the birthday rush.'),
  ('set-up-the-bathroom-m1', 'Set up the bathroom before she comes home — don''t make her ask for things.', '["Fill the peri bottle and put it by the toilet.", "Put ice packs in the freezer.", "Keep pads within reach.", "Put a soft cushion by every chair she''ll sit in."]'::jsonb, 'She''ll be sore in a way that makes fetching things genuinely difficult — having it ready beats being reactive.'),
  ('understand-perineal-healing-m1', 'Learn what normal perineal healing looks like, since she may downplay it.', '["Learn what''s normal: swelling, stinging, gradual improvement.", "Learn what isn''t: increasing pain after day five, foul smell, fever."]'::jsonb, 'She may downplay all of it, so knowing the difference yourself matters.'),
  ('handle-the-first-toilet-fear-m1', 'Help with the first-bowel-movement fear, which can lead to constipation and strain.', '["Keep fibre-rich food and plenty of water in front of her.", "Check with the doctor about a stool softener and have it at home before she needs it.", "Treat the subject as completely normal so she can tell you how it''s going."]'::jsonb, 'Fear of the first bowel movement leads to holding on, then constipation, then straining on the stitches.'),
  ('know-the-prolapse-signs-m2', 'Know the prolapse signs — common, rarely discussed, very treatable early.', '["Learn the signs: heaviness or dragging in the pelvis, a sensation of a bulge, symptoms worse by evening.", "Treat any mention of these as a physio referral, not a wait-and-see."]'::jsonb, 'This is common after vaginal delivery, rarely discussed, and very treatable with physiotherapy when caught early.'),
  ('take-over-standing-tasks-m3', 'Take over the standing tasks — prolonged standing worsens pelvic floor symptoms.', '["Take over cooking, washing up, queueing, and the school run for older kids where you can."]'::jsonb, 'Prolonged standing worsens pelvic floor symptoms in the early months, and this directly reduces hers.'),
  ('understand-why-she-is-still-sore-m4', 'Understand why she''s still sore — it''s not slow healing or in her head.', '["Ask whether sitting or intercourse is still uncomfortable.", "Take the answer seriously.", "Cover the childcare so she can get to a physiotherapist."]'::jsonb, 'Scar tissue tightness and pelvic floor overactivity are both real and both treatable — this is not slow healing on her part.'),
  ('ask-about-intercourse-pain-m6', 'If sex is painful, raise it kindly — her comfort is the goal, not your access.', '["Raise the topic kindly.", "Make clear the goal is her comfort, not your access.", "Suggest physiotherapy, since it treats scar tightness and pelvic floor overactivity effectively."]'::jsonb, 'This is not something she should be enduring quietly or waiting out.'),
  ('watch-for-the-signs-she-will-not-mention-m7', 'Ask directly about leaking, heaviness or pain — she likely won''t raise it herself.', '["Ask directly about leaking when she coughs, sneezes, laughs or lifts the baby, a heaviness or dragging feeling, and pain during sex.", "Keep it a low-key question, not a big conversation."]'::jsonb, 'Most women never raise these, either assuming they''re permanent or finding them embarrassing — all are treatable by a women''s health physiotherapist.'),
  ('cover-the-impact-test-window-m9', 'Cover the childcare so she can properly test for leaking before running.', '["Cover the childcare so she can test for leaking under impact.", "Arrange a physio visit if the test fails."]'::jsonb, 'Returning to running too early causes problems that take much longer to fix than waiting would have.'),
  ('make-sure-a-year-isn-t-settled-for-m12', 'Make sure leaking, heaviness or pain hasn''t quietly become her new normal.', '["Ask gently whether leaking, heaviness, or pain during sex is still happening.", "Help her get a physio referral if so.", "Cover the time for the appointment."]'::jsonb, 'Many women quietly accept these as the new normal by twelve months, when none of them have to be.'),
  ('pt-kangaroo-care-is-for-fathers-too', 'Kangaroo care isn''t only for mothers — ask the NICU team when you can start.', '["Ask the NICU team when you can start kangaroo care.", "Hold your baby skin-to-skin on your bare chest.", "Take turns with her so she can rest."]'::jsonb, 'This gives your baby warmth and gives you time together that no one else can.'),
  ('pt-run-the-nicu-logistics', 'Take the NICU logistics completely — driving, packing, pump parts, paperwork.', '["Drive her to and from the hospital.", "Pack a bag with snacks, water, a cushion and a phone charger.", "Wash and sterilise pump parts, and label and carry expressed milk.", "Handle bills and paperwork."]'::jsonb, 'After a caesarean she should not be driving or lifting at all, so this load is yours to carry completely.'),
  ('pt-protect-her-expressing', 'Protect her expressing sessions, especially the night ones.', '["Set up the night expressing session with her.", "Bring water and a snack.", "Wash the parts afterward and let her go straight back to sleep.", "Never comment on how much milk she made."]'::jsonb, 'Small amounts are normal early on, and pressure makes it harder — your job is to make the session as easy as possible, not to track the output.'),
  ('pt-one-update-for-the-family', 'Take over the daily family update, and shut down any suggestion the birth was her fault.', '["Send one short message to the family group each evening.", "Handle questions about why the baby came early yourself.", "Shut down any suggestion that it was her fault."]'::jsonb, 'One message a day saves her from answering the same questions all day.'),
  ('pt-be-there-for-the-big-conversations', 'Be there for doctors'' rounds and consent discussions, and take notes.', '["Be there for doctors'' rounds, consent discussions and progress updates when you can.", "Write things down and ask what the next steps are.", "Ask the same question twice if you didn''t understand.", "Share the notes with her."]'::jsonb, 'These are hard to take in when you''re frightened — sharing notes means neither of you carries it alone.'),
  ('pt-your-own-stress-counts', 'Your own stress as a NICU father counts too, even while staying strong for her.', '["Watch for constant worry, anger, numbness, avoiding the hospital, or reliving frightening moments.", "Talk to someone.", "Tell a doctor if it persists."]'::jsonb, 'Studies of NICU parents find post-traumatic stress in fathers as well as mothers, sometimes at similar levels — it''s easy to ignore when you feel you have to stay strong for her.'),
  ('pt-own-the-follow-up-calendar', 'Own the follow-up calendar — the eye screening is easy to miss and serious if missed.', '["Get every follow-up date in writing before leaving hospital: eye screening, hearing checks, growth checks, vaccinations, development follow-ups.", "Put them all in one calendar that you own."]'::jsonb, 'The eye screening in particular often falls after discharge and is easy to miss, with serious consequences.'),
  ('pt-get-the-home-ready', 'Get the home ready for a baby more vulnerable to infection, before discharge.', '["Set up a hand-washing point at the door.", "Set a clear rule on visitors.", "Make a plan for turning away anyone who is unwell."]'::jsonb, 'You are the one who can hold this line with relatives without it costing her.'),
  ('pt-explain-corrected-age-to-the-family', 'Learn and explain corrected age before the family comparisons start.', '["Learn corrected age: the age counted from the due date, not the birth date.", "Explain it to relatives before the comparisons start."]'::jsonb, 'A baby born two months early is expected to do what a baby two months younger does — saying this first heads off the comparisons.'),
  ('pt-watch-her-again-after-discharge', 'Ask how she''s doing weeks after discharge — the NICU stress can hit hardest then.', '["Ask her how she''s doing in the weeks after discharge, not just while the baby was in hospital.", "Watch for constant checking on the baby''s breathing, panic at alarm-like sounds, or reliving frightening moments."]'::jsonb, 'Coming home can be when the stress of the NICU hits hardest, for her and for you.')
) as v(id, short_description, steps, why_this)
where father_activities.id = v.id;
